mapper.select:
SELECT m.* FROM user_memory m WHERE m.user_id = #{userId} AND (#{kbId} = 0 OR m.kb_id = #{kbId}) AND m.is_deleted = false AND (m.expires_at IS NULL OR m.expires_at > #{now})
AND LOWER(m.content) LIKE LOWER(CONCAT('%', #{query}, '%'))
ORDER BY m.updated_at DESC LIMIT #{limit} OFFSET #{offset}
